import React from 'react';
import { AlgorithmicSignalTrackRecord } from '../AlgorithmicSignalTrackRecord';

/**
 * GlobalSignalTrackerModal
 * Allows investors to audit all historical and active quantitative signals
 * generated by Drabyashree NEPSE, verifying real out-of-sample accuracy.
 *
 * Wraps the comprehensive AlgorithmicSignalTrackRecord component.
 */
export function GlobalSignalTrackerModal({
  isOpen = true,
  onClose,
  marketStocks = [],
  inlineMode = false,
  onSelectStock,
}) {
  return (
    <AlgorithmicSignalTrackRecord
      isOpen={isOpen}
      onClose={onClose}
      marketStocks={marketStocks}
      inlineMode={inlineMode}
      onSelectStock={onSelectStock}
    />
  );
}

export default GlobalSignalTrackerModal;
